export class Toast{constructor(){this.animation=Object.freeze(["fade","slide","plain"]),this.type=Object.freeze(["info","warning","error","success"]),this.position=Object.freeze(["bottom-left","bottom-right","bottom-center","top-right","top-left","top-center","mid-center"])}static basic(t,i,o){$.toast({heading:i,text:o,showHideTransition:"slide",icon:t,position:"top-center",loader:!0,loaderBg:"#9EC600",stack:!1})}static operacion_exitosa(t){$.toast({heading:"Operación exitosa",text:t,showHideTransition:"slide",icon:"success",position:"top-center",loader:!0,loaderBg:"#9EC600",stack:!1})}static operacion_informativa(t){$.toast({heading:"Importante",text:t,showHideTransition:"slide",icon:"info",position:"top-center",loader:!0,loaderBg:"#9EC600",stack:!1})}static operacion_erronea(t){$.toast({heading:"Operación errónea",text:t,showHideTransition:"slide",icon:"error",position:"top-center",loader:!0,loaderBg:"#9EC600",stack:!1})}static notificacion_lateral(t){$.toast({heading:"Notificación",text:t,showHideTransition:"fade",icon:"info",position:"top-right",loader:!1,hideAfter:4e3,stack:5})}static info_lateral(t,i){$.toast({heading:t,text:i,showHideTransition:"slide",icon:"info",position:"top-right",loader:!0,loaderBg:"#3498db",hideAfter:!1,stack:3})}static advertencia_lateral(t){$.toast({heading:"Advertencia",text:t,showHideTransition:"slide",icon:"warning",position:"top-right",loader:!0,loaderBg:"#f39c12",stack:!1})}static exito_lateral(t){$.toast({heading:"Completado",text:t,showHideTransition:"fade",icon:"success",position:"bottom-right",loader:!0,loaderBg:"#2ecc71",stack:3,hideAfter:3e3})}static info_inferior(t){$.toast({heading:"Información",text:t,showHideTransition:"plain",icon:"info",position:"bottom-center",loader:!1,hideAfter:5e3,stack:!1})}static progreso_inferior(t){$.toast({heading:"Procesando...",text:t,showHideTransition:"slide",icon:"info",position:"bottom-left",loader:!0,loaderBg:"#9EC600",hideAfter:!1,stack:!1})}static alerta_superior_izquierda(t){$.toast({heading:"Alerta",text:t,showHideTransition:"slide",icon:"warning",position:"top-left",loader:!0,loaderBg:"#e67e22",stack:4})}static mensaje_central(t,i){$.toast({heading:t,text:i,showHideTransition:"fade",icon:"info",position:"mid-center",loader:!1,hideAfter:6e3,stack:!1})}static notificacion_rapida(t){$.toast({text:t,showHideTransition:"fade",icon:"success",position:"top-right",loader:!1,hideAfter:2e3,stack:5})}static error_critico(t){$.toast({heading:"Error Crítico",text:t,showHideTransition:"slide",icon:"error",position:"mid-center",loader:!1,hideAfter:!1,stack:!1,bgColor:"#c0392b",textColor:"#fff"})}static actualizacion_disponible(t){$.toast({heading:"Nueva actualización",text:t,showHideTransition:"slide",icon:"info",position:"bottom-right",loader:!1,hideAfter:1e4,stack:!1,bgColor:"#34495e",textColor:"#ecf0f1"})}static guardado_automatico(){$.toast({text:"Cambios guardados automáticamente",showHideTransition:"fade",icon:"success",position:"bottom-right",loader:!1,hideAfter:2e3,stack:!1})}static personalizado(t){const i={heading:"",text:"",showHideTransition:"slide",icon:"info",position:"top-right",loader:!0,loaderBg:"#9EC600",stack:!1,hideAfter:3e3};$.toast({...i,...t})}}